# Map phase — both mappers emit with user_id as key
def map_events(_, row):       # row = {user_id, event_type, ts}
    emit(row['user_id'], ('E', row))

def map_users(_, row):        # row = {user_id, name, country}
    emit(row['user_id'], ('U', row))

# Reduce phase — receives all records for one user_id
def reduce(user_id, records):
    user = None
    events = []
    for tag, data in records:
        if tag == 'U': user = data
        else: events.append(data)
    for ev in events:
        if user: emit({**ev, 'name': user['name']})

# Broadcast hash join: no reduce phase needed
class BroadcastMapper:
    def setup(self):
        # Load small table from Distributed Cache into memory
        self.users = {}
        with open('users.tsv') as f:
            for line in f:
                uid, name, country = line.strip().split('\t')
                self.users[uid] = {'name': name, 'country': country}

    def map(self, _, event_row):
        user = self.users.get(event_row['user_id'])
        if user:
            emit({**event_row, 'name': user['name']})

# Pregel-style PageRank vertex program
# Each superstep: receive rank contributions from neighbours,
# update own rank, send updated contribution to own neighbours

def vertex_compute(vertex, messages):
    if superstep == 0:
        vertex.rank = 1.0 / num_vertices
    else:
        # Sum incoming rank contributions
        rank_sum = sum(messages)
        vertex.rank = 0.15 / num_vertices + 0.85 * rank_sum

    # Send contribution to each out-neighbour
    for neighbour in vertex.out_edges:
        send_message(neighbour, vertex.rank / len(vertex.out_edges))

    # Halt when rank change is negligible
    if abs(vertex.rank - vertex.prev_rank) < 0.0001:
        vertex.vote_to_halt()
